function drawHouse(sx,sy){ctx.fillStyle='#3b3227';ctx.fillRect(sx+2,sy+28,90,54);ctx.fillStyle='#a88c5c';ctx.fillRect(sx+7,sy+34,80,46);ctx.fillStyle='#66513b';ctx.beginPath();ctx.moveTo(sx-4,sy+37);ctx.lineTo(sx+45,sy+3);ctx.lineTo(sx+97,sy+37);ctx.closePath();ctx.fill();ctx.fillStyle='#b46d50';ctx.beginPath();ctx.moveTo(sx+3,sy+35);ctx.lineTo(sx+45,sy+8);ctx.lineTo(sx+91,sy+35);ctx.closePath();ctx.fill();ctx.fillStyle='#7c503e';ctx.fillRect(sx+36,sy+49,20,31);ctx.fillStyle='#e6c374';ctx.fillRect(sx+14,sy+46,14,13);ctx.fillRect(sx+64,sy+46,14,13);ctx.fillStyle='#f0d48d';ctx.fillRect(sx+20,sy+48,2,9);ctx.fillRect(sx+69,sy+48,2,9);ctx.fillStyle='#c2a171';ctx.fillRect(sx+2,sy+78,91,5)}
function drawCharacter(sx,sy,kind='player',frame=0){ctx.save();ctx.translate(sx,sy);ctx.fillStyle='#26342c';ctx.beginPath();ctx.ellipse(0,17,13,6,0,0,Math.PI*2);ctx.fill();if(kind==='slime'){ctx.fillStyle='#9acb85';ctx.beginPath();ctx.ellipse(0,7,13,11+Math.sin(frame)*1.5,0,Math.PI,0);ctx.lineTo(13,11);ctx.lineTo(-13,11);ctx.fill();ctx.fillStyle='#3b603e';ctx.fillRect(-5,5,2,3);ctx.fillRect(4,5,2,3);ctx.fillStyle='#d3e7a4';ctx.fillRect(-7,1,4,2);ctx.restore();return}
 let isNpc=kind==='npc';ctx.fillStyle=isNpc?'#bd876b':'#d6a77a';ctx.fillRect(-7,-8,14,15);ctx.fillStyle=isNpc?'#e7d6a2':'#dfc27e';ctx.fillRect(-8,-11,16,6);ctx.fillStyle=isNpc?'#9c6654':'#765541';ctx.fillRect(-7,-15,14,7);ctx.fillStyle='#453b35';ctx.fillRect(-3,-5,2,2);ctx.fillRect(3,-5,2,2);ctx.fillStyle=isNpc?'#587254':'#4d7155';ctx.fillRect(-9,6,18,10);ctx.fillStyle='#383d34';let step=Math.sin(frame*8)>0?2:0;ctx.fillRect(-7,15,5,step+5);ctx.fillRect(2,15,5,7-step);if(!isNpc){ctx.fillStyle='#f1d891';ctx.fillRect(8,-5,3,14);ctx.fillStyle='#d2b45f';ctx.fillRect(7,3,5,2)}ctx.restore()}
function visibleProps(){return props.filter(p=>Math.abs(p.x*T-player.x)<700&&Math.abs(p.y*T-player.y)<520)}
function drawWorld(){let dpr=Math.min(devicePixelRatio||1,2),rect=canvas.getBoundingClientRect();if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);ctx.clearRect(0,0,W,H);
 camera.x=Math.max(0,Math.min(worldW*T-W,player.x-W/2));camera.y=Math.max(0,Math.min(worldH*T-H,player.y-H/2));let ox=-camera.x,oy=-camera.y;
 let startX=Math.floor(camera.x/T),startY=Math.floor(camera.y/T);for(let y=startY;y<Math.min(worldH,startY+15);y++)for(let x=startX;x<Math.min(worldW,startX+22);x++)drawTile(x,y,ox+x*T,oy+y*T);
 let visible=visibleProps().sort((a,b)=>a.y-b.y);
 for(const p of visible){let sx=p.x*T+ox,sy=p.y*T+oy;if(p.type==='tree')drawTree(sx,sy,p.scale);else if(p.type==='rock')drawRock(sx,sy);else if(p.type==='house')drawHouse(sx,sy);else if(p.type==='npc'){drawCharacter(sx+24,sy+22,'npc',minutes/10);ctx.fillStyle='#f0e2bb';ctx.font='12px Georgia';ctx.textAlign='center';ctx.fillText('Mira',sx+24,sy-2)}else if(p.type==='slime')drawCharacter(sx+24,sy+26,'slime',performance.now()/250);else if(p.type==='berry'){ctx.fillStyle='#35563c';ctx.fillRect(sx+8,sy+24,31,15);ctx.fillStyle='#577846';ctx.beginPath();ctx.arc(sx+23,sy+22,15,Math.PI,0);ctx.fill();ctx.fillStyle='#b95b6a';ctx.fillRect(sx+14,sy+17,5,5);ctx.fillRect(sx+26,sy+21,5,5);ctx.fillRect(sx+23,sy+11,4,4)}else if(p.type==='herb'){ctx.strokeStyle='#87aa67';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(sx+22,sy+39);ctx.lineTo(sx+16,sy+22);ctx.moveTo(sx+22,sy+39);ctx.lineTo(sx+29,sy+18);ctx.moveTo(sx+22,sy+39);ctx.lineTo(sx+21,sy+15);ctx.stroke();ctx.fillStyle='#b9cc83';ctx.fillRect(sx+13,sy+20,7,3);ctx.fillRect(sx+26,sy+16,7,3)}else if(p.type==='flower'){ctx.fillStyle='#e3cc85';ctx.fillRect(sx+20,sy+28,4,4);ctx.fillStyle='#e8a7a1';ctx.fillRect(sx+17,sy+26,3,3);ctx.fillRect(sx+24,sy+26,3,3);ctx.fillStyle='#779754';ctx.fillRect(sx+21,sy+31,2,7)}}
 drawCharacter(player.x+ox,player.y+oy,'player',player.walk);
 // soft canopy at the edge keeps the map atmospheric without obscuring play
 const night=Math.max(0,Math.min(.48,(Math.abs(minutes-760)-260)/500));if(night>0){ctx.fillStyle=`rgba(18,30,54,${night})`;ctx.fillRect(0,0,W,H)}
 // subtle sun motes
 if(minutes>400&&minutes<1100){ctx.fillStyle='#f8e7ae13';for(let i=0;i<8;i++){let x=(i*163+performance.now()*.008)%W,y=(i*83+performance.now()*.004)%H;ctx.fillRect(x,y,2,2)}}
}
function distance(p){return Math.hypot(p.x*T+24-player.x,p.y*T+24-player.y)}
function closestTarget(){let list=props.filter(p=>distance(p)<68&&['npc','slime','berry','herb','rock','tree','house'].includes(p.type));return list.sort((a,b)=>distance(a)-distance(b))[0]}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function openDialogue(title,text){dialogueOpen=true;document.querySelector('#dialogTitle').textContent=title;document.querySelector('#dialogText').textContent=text;document.querySelector('#dialogue').classList.add('open')}
function closeDialogue(){dialogueOpen=false;document.querySelector('#dialogue').classList.remove('open')}

