function closeDialogue(){dialogueOpen=false;document.querySelector('#dialogue').classList.remove('open')}
function gainXP(n){player.xp+=n;if(player.xp>=100){player.xp-=100;player.level=(player.level||1)+1;player.hp=100;toast(`✨ Nível ${player.level}! Você ficou mais forte.`)}updateHUD()}
function interact(){if(dialogueOpen){closeDialogue();return}let p=closestTarget();if(!p){useSelected();return}
 if(p.type==='npc'){let text=items.berry>0?'Você encontrou amoras? O bosque tem um jeito especial de cuidar de quem o explora. Leve algumas para a viagem — e aceite este agradecimento.':'Olá, viajante! Sou Mira. Se encontrar amoras pelo bosque, guarde algumas: são ótimas para recuperar as forças. Mas não precisa ter pressa — aproveite o vale!';if(items.berry>=2){items.berry-=2;player.coins+=8;items.herb++;gainXP(12);text='Que belas amoras! Obrigada por compartilhar. Aqui, algumas moedas e uma erva que colhi perto do riacho. Volte quando quiser, viajante.';found++;}openDialogue('Mira, a guardiã do bosque',text);updateHUD();return}
 if(p.type==='slime'){if(player.st<12){toast('Sem energia para lutar. Descanse um pouco!');return}player.st-=12;player.walk+=1;p.hp=(p.hp||2)-1;if(p.hp<=0){props.splice(props.indexOf(p),1);player.coins+=3;items.berry++;found++;gainXP(16);toast('Criatura vencida! +3 moedas · +1 amora · +16 XP')}else toast('Você acertou a criatura! Ela ainda está aqui.');updateHUD();return}
 if(p.type==='berry'){items.berry++;player.st=Math.max(0,player.st-3);props.splice(props.indexOf(p),1);found++;gainXP(3);toast('Amoras silvestres guardadas. 🍒');updateHUD();return}
 if(p.type==='herb'){items.herb++;props.splice(props.indexOf(p),1);found++;gainXP(4);toast('Erva-doce colhida. 🌿');updateHUD();return}
 if(p.type==='tree'){if(player.st<8){toast('Você precisa descansar antes de coletar.');return}items.wood+=2;player.st-=8;props.splice(props.indexOf(p),1);found++;gainXP(5);toast('Madeira coletada. +2 🪵');updateHUD();return}
 if(p.type==='rock'){if(player.st<7){toast('Você precisa descansar antes de coletar.');return}items.stone+=2;player.st-=7;props.splice(props.indexOf(p),1);found++;gainXP(5);toast('Pedra coletada. +2 ◈');updateHUD();return}
