 const inventory=document.querySelector('#inventory');const rows=[['berry','🍒','Amoras'],['wood','🪵','Madeira'],['stone','◈','Pedra'],['herb','🌿','Ervas']];inventory.innerHTML=rows.map(([k,icon,name])=>`<div class="inv-cell"><div class="inv-slot">${items[k]?icon:'<span class="empty-slot">·</span>'}<span class="inv-count">${items[k]||''}</span></div><div class="inv-label">${name}</div></div>`).join('');
