function load(){try{let s=JSON.parse(localStorage.getItem('valelivre-save'));if(s){Object.assign(player,s.player);Object.assign(items,s.items);day=s.day||1;minutes=s.minutes||500;found=s.found||0}}catch(e){}}
load();updateHUD();
function isBlocked(x,y){let tx=Math.floor(x/T),ty=Math.floor(y/T);if(tx<0||ty<0||tx>=worldW||ty>=worldH)return true;let type=tileAt(tx,ty);if(type==='water')return true;return props.some(p=>['tree','rock','house'].includes(p.type)&&Math.abs(p.x*T+24-x)<27&&Math.abs(p.y*T+26-y)<25)}
function frame(now){let dt=Math.min(.04,(now-lastTime)/1000||0);lastTime=now;let vx=0,vy=0;if(!dialogueOpen){if(keys.ArrowUp||keys.w||keys.W||touch.up)vy--;if(keys.ArrowDown||keys.s||keys.S||touch.down)vy++;if(keys.ArrowLeft||keys.a||keys.A||touch.left)vx--;if(keys.ArrowRight||keys.d||keys.D||touch.right)vx++;}
 if(vx||vy){let len=Math.hypot(vx,vy);vx=vx/len*145*dt;vy=vy/len*145*dt;if(vy<0)player.dir='up';else if(vy>0)player.dir='down';else if(vx<0)player.dir='left';else player.dir='right';if(!isBlocked(player.x+vx,player.y))player.x+=vx;if(!isBlocked(player.x,player.y+vy))player.y+=vy;player.walk+=dt*10;player.st=Math.max(0,player.st-dt*.42)}else player.st=Math.min(100,player.st+dt*2.5);
 minutes+=dt*2.8;if(minutes>=1440){minutes-=1440;day++}let hours=Math.floor(minutes/60),mins=Math.floor(minutes%60);document.querySelector('#timeTag').textContent=`${hours>6&&hours<19?'☀':'☾'} Dia ${day} · ${String(hours).padStart(2,'0')}:${String(mins).padStart(2,'0')}`;
 drawWorld();let mp=document.querySelector('#mapMarker');mp.style.left=(Math.max(3,Math.min(94,player.x/(worldW*T)*100)))+'%';mp.style.top=(Math.max(3,Math.min(94,player.y/(worldH*T)*100)))+'%';requestAnimationFrame(frame)}
requestAnimationFrame(frame);
const touch={up:false,down:false,left:false,right:false};document.querySelectorAll('[data-dir]').forEach(btn=>{let dir=btn.dataset.dir;btn.addEventListener('pointerdown',e=>{e.preventDefault();touch[dir]=true;btn.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,()=>touch[dir]=false))});
document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if([' ','e','E','Enter'].includes(e.key)&&!e.repeat)interact();if(/^[1-4]$/.test(e.key)){selected=Number(e.key)-1;updateHUD()}if(e.key==='Escape')closeDialogue()});document.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
document.querySelector('#actionBtn').onclick=interact;document.querySelector('#touchInteract').onclick=interact;document.querySelector('#dialogClose').onclick=closeDialogue;document.querySelector('#craftBtn').onclick=craft;document.querySelector('#saveBtn').onclick=save;document.querySelector('#soundBtn').onclick=e=>{mute=!mute;e.currentTarget.classList.toggle('active',mute);toast(mute?'Som ambiente desligado.':'Som ambiente ligado.')};
// Tap a nearby spot to walk there; long-pressing the action button remains comfortable on phones.
let tapStart=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&!e.target.closest('.mobile-controls'))tapStart={x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerup',e=>{if(tapStart){let dx=e.clientX-tapStart.x,dy=e.clientY-tapStart.y;if(Math.hypot(dx,dy)>20){if(Math.abs(dx)>Math.abs(dy))keys[dx>0?'d':'a']=true;else keys[dy>0?'s':'w']=true;setTimeout(()=>{keys.w=keys.a=keys.s=keys.d=false},320)}tapStart=null}});
</script>
</body>
</html>

